// Evaluates the specified postfix expression.
public int evaluate(String expr) {
  int op1, op2, result = 0;
  String token;
  Scanner parser = new Scanner(expr);
  while (parser.hasNext()) {
    token = parser.next();
    if (isOperator(token)) {
                                                // if token is + - * or /
      op2 = stack.pop();
                                                // pop 2nd Integer operand
      op1 = stack.pop();
                                                // pop 1st Integer operand
      result = evaluateSingleOperator(token.charAt(0), op1, op2);
      stack.push(result);
                                                // push int result on the stack
    }
    else
                                                // token is an integer operand
      stack.push(Integer.valueOf(token))); // push Integer operand
  }
  return result;
                                                // return final expression result
}

