  this(DEFAULT_CAPACITY);
}

// Creates an empty stack using the specified capacity.
// initialCapacity is the initial capacity of the array
public ArrayStack(int initialCapacity) {
  top = 0;
  array = (T[]) new Object[initialCapacity];
}

